












import { BaseVueComponent, Component, State, Watch, Mutation, Action } from "sunway-vue";
import { CompFile } from "@/com/sunwayworld/framework/file/CompFile";
import * as CodeMirror from "codemirror";
import "codemirror/theme/monokai.css";
import "codemirror/lib/codemirror.css";
import "codemirror/mode/javascript/javascript";
import "codemirror/mode/clike/clike";
import "codemirror/mode/go/go";
import "codemirror/mode/htmlmixed/htmlmixed";
import "codemirror/mode/http/http";
import "codemirror/mode/php/php";
import "codemirror/mode/python/python";
import "codemirror/mode/http/http";
import "codemirror/mode/sql/sql";
import "codemirror/mode/vue/vue";
import "codemirror/mode/xml/xml";
import "codemirror/addon/scroll/simplescrollbars.css";
import "codemirror/addon/scroll/simplescrollbars";
import "codemirror/addon/hint/show-hint";
import "codemirror/addon/hint/javascript-hint";
import "codemirror/addon/hint/sql-hint";
import "codemirror/addon/hint/html-hint";
import "codemirror/addon/hint/xml-hint";
import "codemirror/addon/hint/anyword-hint";
import "codemirror/addon/hint/css-hint";
import "codemirror/addon/hint/show-hint.css";
import "codemirror/addon/fold/markdown-fold";
import "codemirror/mode/meta";
import "codemirror/addon/fold/foldgutter.css";
import "codemirror/addon/fold/foldcode";
import "codemirror/addon/fold/brace-fold";
import "codemirror/addon/selection/active-line";
import { PageDesignMutations, PageDesignActions } from "../main/store/pageDesignStore";
import { MaskUtils } from "../../framework/utils/MaskUtils";

@Component
export default class CodeEditPanel extends BaseVueComponent<object> {
    private editor?: CodeMirror.EditorFromTextArea;

    @State("compData")
    private comp!: Gikam.component.BaseComp;

    @Mutation(PageDesignMutations.SET_ACTIVATED_COMP_FILE)
    private setActivatedCompFile!: (file: CompFile) => void;

    @Mutation(PageDesignMutations.SET_CODE_EDITOR)
    private setCodeEditor!: (editor: CodeMirror.EditorFromTextArea) => void;

    @Action(PageDesignActions.SAVE_FILE)
    private saveFile!: () => void;

    @Mutation(PageDesignMutations.SET_FILE_EDITING)
    private setFileEditing!: (isEditing: boolean) => void;

    @State
    private fileEditing!: boolean;

    //当前激活的组件类型
    private compType = "";

    //激活的组件所在的js文件地址
    private jsFileUrl = "";

    //最初的js文件内容，用于判断是否进行了修改
    private initFileText = "";

    private mounted() {
        this.editor = CodeMirror.fromTextArea(this.$refs.container as HTMLTextAreaElement, {
            theme: "monokai",
            mode: "javascript",
            extraKeys: { Ctrl: "autocomplete" },
            tabSize: 4,
            smartIndent: true,
            scrollbarStyle: "overlay",
            lineNumbers: true,
            indentWithTabs: true
        });
        this.setCodeEditor(this.editor);
        this.initEvent();
    }

    @Watch("comp")
    private async watchComp() {
        const comp = this.comp;
        if (!this.comp) {
            this.clean();
            return;
        }
        MaskUtils.showFullScreenMask("组件初始化，请稍候");
        this.compType = this.comp.$type;
        const pageUrl = comp.$window.history[comp.$window.history.length - 1];
        const compFile = new CompFile(pageUrl, comp.options.id);
        await compFile.init();
        this.setActivatedCompFile(compFile);
        this.jsFileUrl = compFile.fileUrl;
        const text = compFile.getText();
        if (this.editor && text) {
            this.initFileText = text;
            this.editor.setValue(text);
            this.editor.clearHistory();
        }
        MaskUtils.closeFullScreenMask(500);
    }

    private clean() {
        this.compType = "";
        this.jsFileUrl = "";
        if (this.editor) {
            this.initFileText = this.editor.getValue();
        }
    }

    private initEvent() {
        document.onkeydown = e => {
            if (e.ctrlKey && e.keyCode === 83) {
                this.saveFile();
                return false;
            }
        };
        this.initSaveEvent();
    }

    private initSaveEvent() {
        if (!this.editor) {
            return;
        }
        const editor = this.editor;
        editor.on("update", () => {
            Gikam.finalDelay(
                "codeSave",
                () => {
                    if (editor.getValue() === this.initFileText) {
                        this.setFileEditing(false);
                    } else {
                        this.setFileEditing(true);
                    }
                },
                1000
            );
        });
    }

    @Watch("fileEditing")
    private watchFileEditing(newValue: boolean, oldValue: boolean) {
        if (oldValue === true && newValue === false) {
            if (this.editor) {
                this.initFileText = this.editor.getValue();
            }
        }
    }
}
